/* unsigned int rlLoadShaderBuffer(unsigned int size, const void * data, int usageHint) */
static Janet jrl_cfun_rlLoadShaderBuffer(int32_t argc, Janet *argv) {
    janet_fixarity(argc, 3);
    unsigned int size = jrl_get_uint(argv, 0);
    int usageHint = jrl_get_int(argv, 2);
    JanetByteView jrl_v_data = jrl_get_bytes(argv, 1, 1);
    const void* data = (const void*) jrl_v_data.bytes;
    if (jrl_v_data.bytes != NULL && jrl_v_data.len < (int32_t) (size))
        janet_panicf("argument %d: expected at least %d bytes, got %d", 1, (int32_t) (size), jrl_v_data.len);
    unsigned int jrl_ret = rlLoadShaderBuffer(size, data, usageHint);
    Janet jrl_value = janet_wrap_number((double) jrl_ret);
    return jrl_value;
}

