/* void rlReadShaderBuffer(unsigned int id, void * dest, unsigned int count, unsigned int offset) */
static Janet jrl_cfun_rlReadShaderBuffer(int32_t argc, Janet *argv) {
    janet_fixarity(argc, 3);
    unsigned int id = jrl_get_uint(argv, 0);
    unsigned int count = jrl_get_uint(argv, 1);
    unsigned int offset = jrl_get_uint(argv, 2);
    int32_t jrl_size_dest = (int32_t) (count);
    JanetBuffer *jrl_ob_dest = janet_buffer(jrl_size_dest);
    void* dest = jrl_ob_dest->data;
    rlReadShaderBuffer(id, dest, count, offset);
    jrl_ob_dest->count = jrl_size_dest;
    return janet_wrap_buffer(jrl_ob_dest);
}

